fn clone_vec(b: &Vec<f64>) -> Vec<f64> {
    b.clone()
}

fn solve(a: Vec<Vec<f64>>, b: Vec<f64>) -> Vec<f64> {
    let n = b.len();
    assert!(a.len() == n, "Matrix must have the same number of rows as the length of b");
    for row in &a {
        assert!(row.len() == n, "Matrix must be square");
    }

    // Build the augmented matrix [A | b]
    let mut aug: Vec<Vec<f64>> = Vec::with_capacity(n);
    for i in 0..n {
        let mut row = Vec::with_capacity(n + 1);
        row.extend_from_slice(&a[i]);
        row.push(b[i]);
        aug.push(row);
    }

    // Forward elimination with partial pivoting
    for i in 0..n {
        // Find pivot row
        let mut max_row = i;
        let mut max_val = aug[i][i].abs();
        for k in (i + 1)..n {
            let val = aug[k][i].abs();
            if val > max_val {
                max_val = val;
                max_row = k;
            }
        }
        assert!(max_val != 0.0, "Matrix is singular or nearly singular");

        // Swap current row with pivot row if needed
        if max_row != i {
            aug.swap(i, max_row);
        }

        // Normalize pivot row
        let pivot = aug[i][i];
        for j in i..=n {
            aug[i][j] /= pivot;
        }

        // Eliminate below
        for k in (i + 1)..n {
            let factor = aug[k][i];
            for j in i..=n {
                aug[k][j] -= factor * aug[i][j];
            }
        }
    }

    // Back substitution
    let mut x = vec![0.0; n];
    for i in (0..n).rev() {
        let mut sum = aug[i][n];
        for j in (i + 1)..n {
            sum -= aug[i][j] * x[j];
        }
        x[i] = sum; // Row i has been normalized so pivot is 1
    }

    x
}

// Example usage
fn main() {
    let a = vec![
        vec![2.0, 1.0, -1.0],
        vec![-3.0, -1.0, 2.0],
        vec![-2.0, 1.0, 2.0],
    ];
    let b = vec![8.0, -11.0, -3.0];
    let x = solve(a, b);
    println!("Solution x = {:?}", x);

    let original = vec![1.0, 2.0, 3.0];
    let cloned = clone_vec(&original);
    println!("Cloned vector = {:?}", cloned);
}